package com.example.editor.metamodel.export;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;
import org.springframework.stereotype.Component;
import com.example.editor.metamodel.core.MetaAttribute;
import com.example.editor.metamodel.core.MetaClass;
import com.example.editor.metamodel.core.MetaClassKind;
import com.example.editor.metamodel.core.MetaDataType;
import com.example.editor.metamodel.core.MetaOperation;
import com.example.editor.metamodel.core.MetaParameter;
import com.example.editor.metamodel.core.MetaRelation;
import com.example.editor.metamodel.core.MetaTypeReference;
import com.example.editor.metamodel.core.MetaTypeReferenceKind;
import com.example.editor.metamodel.core.Multiplicity;
import com.example.editor.metamodel.design.MetamodelDesignException;
import com.example.editor.metamodel.design.MetamodelDesignException.Reason;

/** Generates an idiomatic dependency-free Go model package from the neutral metamodel. */
@Component
public class GoMetamodelExporter implements MetamodelBinaryExporter {
    /** Descripción: Ejecuta la operación «format» correspondiente a la responsabilidad de GoMetamodelExporter. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ @Override public MetamodelExportFormat format(){return MetamodelExportFormat.GO;}
    /** Descripción: Ejecuta la operación «export» correspondiente a la responsabilidad de GoMetamodelExporter. Entradas: context: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public byte[] export(NeutralMetamodelExportContext context){
        try(ByteArrayOutputStream output=new ByteArrayOutputStream();ZipOutputStream zip=new ZipOutputStream(output,StandardCharsets.UTF_8)){
            add(zip,"model/model.go",buildModel(context));add(zip,"go.mod",goMod(context));add(zip,"README.md",readme(context));zip.finish();return output.toByteArray();
        }catch(IOException exception){throw new MetamodelDesignException(Reason.STORAGE_ERROR,"Could not generate Go export",exception);}
    }

    /** Descripción: Crea o prepara el resultado de «buildModel» dentro de GoMetamodelExporter. Entradas: context: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private String buildModel(NeutralMetamodelExportContext context){
        StringBuilder out=new StringBuilder("// Code generated by HYDRA. DO NOT EDIT.\npackage model\n\n");
        if(usesDate(context))out.append("import \"time\"\n\n");
        context.neutralMetamodel().enums().forEach(value->{String name=MetamodelExportSupport.pascal(value.name(),"GeneratedEnum");out.append("type ").append(name).append(" int\n\nconst (\n");value.literals().forEach(literal->out.append("\t").append(name).append(MetamodelExportSupport.pascal(literal.name(),"Value")).append(" ").append(name).append(" = ").append(literal.value()).append("\n"));out.append(")\n\n");});
        for(MetaDataType value:context.neutralMetamodel().dataTypes())out.append("type ").append(MetamodelExportSupport.pascal(value.name(),"GeneratedType")).append(" string\n\n");
        for(MetaClass value:context.neutralMetamodel().classes())appendClass(out,context,value);
        return out.toString();
    }

    /** Descripción: Ejecuta la operación «appendClass» correspondiente a la responsabilidad de GoMetamodelExporter. Entradas: out: dato de entrada necesario para la operación; context: dato de entrada necesario para la operación; value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ private void appendClass(StringBuilder out,NeutralMetamodelExportContext context,MetaClass value){
        String name=MetamodelExportSupport.pascal(value.name(),"GeneratedClass");
        if(value.kind()==MetaClassKind.INTERFACE){appendInterface(out,context,value,name);return;}
        if(value.kind()==MetaClassKind.ABSTRACT_CLASS)out.append("// ").append(name).append(" represents an abstract neutral model type.\n");
        out.append("type ").append(name).append(" struct {\n");
        for(MetaRelation base:MetamodelExportSupport.superTypeRelationsFrom(context,value.id()))out.append("\t").append(MetamodelExportSupport.pascal(MetamodelExportSupport.relationTargetName(context,base),"GeneratedClass")).append("\n");
        for(MetaAttribute attribute:value.attributes()){String field=MetamodelExportSupport.pascal(attribute.name(),"Value");out.append("\t").append(field).append(" ").append(cardinality(type(context,attribute.type()),attribute.multiplicity())).append(" `json:\"").append(MetamodelExportSupport.camel(attribute.name(),"value"));if(optional(attribute.multiplicity()))out.append(",omitempty");out.append("\"`\n");}
        for(MetaRelation relation:MetamodelExportSupport.structuralRelationsFrom(context,value.id())){String field=MetamodelExportSupport.pascal(relation.name(),"Reference");String target="*"+MetamodelExportSupport.pascal(MetamodelExportSupport.relationTargetName(context,relation),"GeneratedClass");out.append("\t").append(field).append(" ").append(cardinality(target,relation.targetMultiplicity())).append(" `json:\"").append(MetamodelExportSupport.camel(relation.name(),"reference"));if(optional(relation.targetMultiplicity()))out.append(",omitempty");out.append("\"`\n");}
        out.append("}\n\n");
        if(!value.operations().isEmpty()){out.append("type ").append(name).append("Behavior interface {\n");for(MetaOperation operation:value.operations())appendOperation(out,context,operation);out.append("}\n\n");}
    }

    /** Descripción: Ejecuta la operación «appendInterface» correspondiente a la responsabilidad de GoMetamodelExporter. Entradas: out: dato de entrada necesario para la operación; context: dato de entrada necesario para la operación; value: valor de entrada que debe procesarse; name: dato de entrada necesario para la operación. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ private void appendInterface(StringBuilder out,NeutralMetamodelExportContext context,MetaClass value,String name){
        out.append("type ").append(name).append(" interface {\n");
        for(MetaRelation base:MetamodelExportSupport.superTypeRelationsFrom(context,value.id()))out.append("\t").append(MetamodelExportSupport.pascal(MetamodelExportSupport.relationTargetName(context,base),"GeneratedClass")).append("\n");
        for(MetaAttribute attribute:value.attributes())out.append("\tGet").append(MetamodelExportSupport.pascal(attribute.name(),"Value")).append("() ").append(cardinality(type(context,attribute.type()),attribute.multiplicity())).append("\n");
        for(MetaRelation relation:MetamodelExportSupport.structuralRelationsFrom(context,value.id()))out.append("\tGet").append(MetamodelExportSupport.pascal(relation.name(),"Reference")).append("() ").append(cardinality("*"+MetamodelExportSupport.pascal(MetamodelExportSupport.relationTargetName(context,relation),"GeneratedClass"),relation.targetMultiplicity())).append("\n");
        for(MetaOperation operation:value.operations())appendOperation(out,context,operation);out.append("}\n\n");
    }

    /** Descripción: Ejecuta la operación «appendOperation» correspondiente a la responsabilidad de GoMetamodelExporter. Entradas: out: dato de entrada necesario para la operación; context: dato de entrada necesario para la operación; operation: dato de entrada necesario para la operación. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ private void appendOperation(StringBuilder out,NeutralMetamodelExportContext context,MetaOperation operation){out.append("\t").append(MetamodelExportSupport.pascal(operation.name(),"Operation")).append("(");for(int index=0;index<operation.parameters().size();index++){MetaParameter parameter=operation.parameters().get(index);if(index>0)out.append(", ");out.append(MetamodelExportSupport.camel(parameter.name(),"arg")).append(" ").append(cardinality(type(context,parameter.type()),parameter.multiplicity()));}out.append(")");if(!operation.returnsVoid())out.append(" ").append(cardinality(type(context,operation.returnType()),operation.returnMultiplicity()));out.append("\n");}
    /** Descripción: Ejecuta la operación «type» correspondiente a la responsabilidad de GoMetamodelExporter. Entradas: context: dato de entrada necesario para la operación; reference: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private String type(NeutralMetamodelExportContext context,MetaTypeReference reference){if(reference==null)return "any";if(reference.kind()!=MetaTypeReferenceKind.PRIMITIVE){if(reference.kind()==MetaTypeReferenceKind.EXTERNAL)return "any";return MetamodelExportSupport.pascal(MetamodelExportSupport.resolveTypeName(context,reference),"GeneratedType");}return switch(reference.targetId()){case "BOOLEAN"->"bool";case "BYTE"->"int8";case "SHORT"->"int16";case "INTEGER"->"int";case "LONG","BIG_INTEGER"->"int64";case "FLOAT"->"float32";case "DOUBLE","DECIMAL"->"float64";case "BINARY"->"[]byte";case "DATE"->"time.Time";case "OBJECT"->"any";default->"string";};}
    /** Descripción: Ejecuta la operación «cardinality» correspondiente a la responsabilidad de GoMetamodelExporter. Entradas: type: dato de entrada necesario para la operación; multiplicity: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private String cardinality(String type,Multiplicity multiplicity){return multiplicity!=null&&(multiplicity.unbounded()||multiplicity.upperBound()>1)?"[]"+type:type;}
    /** Descripción: Ejecuta la operación «optional» correspondiente a la responsabilidad de GoMetamodelExporter. Entradas: multiplicity: dato de entrada necesario para la operación. Salida: devuelve un indicador que expresa el resultado de la condición. */ private boolean optional(Multiplicity multiplicity){return multiplicity==null||multiplicity.lowerBound()==0;}
    /** Descripción: Ejecuta la operación «usesDate» correspondiente a la responsabilidad de GoMetamodelExporter. Entradas: context: dato de entrada necesario para la operación. Salida: devuelve un indicador que expresa el resultado de la condición. */ private boolean usesDate(NeutralMetamodelExportContext context){boolean attributes=context.neutralMetamodel().classes().stream().flatMap(value->value.attributes().stream()).anyMatch(attribute->isDate(attribute.type()));boolean operations=context.neutralMetamodel().classes().stream().flatMap(value->value.operations().stream()).anyMatch(operation->isDate(operation.returnType())||operation.parameters().stream().anyMatch(parameter->isDate(parameter.type())));return attributes||operations;}
    /** Descripción: Evalúa la condición «isDate» sin modificar el estado externo. Entradas: reference: dato de entrada necesario para la operación. Salida: devuelve un indicador que expresa el resultado de la condición. */ private boolean isDate(MetaTypeReference reference){return reference!=null&&reference.kind()==MetaTypeReferenceKind.PRIMITIVE&&"DATE".equals(reference.targetId());}
    /** Descripción: Ejecuta la operación «goMod» correspondiente a la responsabilidad de GoMetamodelExporter. Entradas: context: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private String goMod(NeutralMetamodelExportContext context){String module=MetamodelExportSupport.camel(context.neutralMetamodel().name(),"hydra_model").toLowerCase(java.util.Locale.ROOT);return "module hydra.generated/"+module+"\n\ngo 1.22\n";}
    /** Descripción: Obtiene la información correspondiente a «readme» dentro de GoMetamodelExporter. Entradas: context: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private String readme(NeutralMetamodelExportContext context){return "# "+context.neutralMetamodel().name()+"\n\nGenerated Go model package from HYDRA's neutral metamodel. Interfaces, inheritance and operation signatures are preserved where the Go type system can express them.\n";}
    /** Descripción: Ejecuta la operación «add» correspondiente a la responsabilidad de GoMetamodelExporter. Entradas: zip: dato de entrada necesario para la operación; path: ruta o ubicación utilizada por la operación; content: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ private void add(ZipOutputStream zip,String path,String content)throws IOException{zip.putNextEntry(new ZipEntry(path));zip.write(content.getBytes(StandardCharsets.UTF_8));zip.closeEntry();}
}
